python - <<'PY'
import json, numpy as np
m=json.load(open('/app/output/live_reobserve/meta.json'))
for c in ['ego','wrist_right']:
 K=np.array(m['cameras'][c]['intrinsic_cv']); E=np.array(m['cameras'][c]['extrinsic_cv']);
 for p in [[.72,-.32,.94],[.49,-.02,.76],[.458,-.13,.76],[.458,-.13,.80],[.458,-.13,.90]]:
  q=E[:3,:3]@p+E[:3,3]; uv=K@q; uv=uv[:2]/uv[2]
  print(c,p,'->',uv.round(1),'zcam',q[2])
PY

